export function InfiniteMovingCards({
  items,
  direction = "left",
}: {
  items: { quote: string; name: string }[];
  direction?: "left" | "right";
}) {
  const loop = [...items, ...items];

  return (
    <div
      className="group relative w-full overflow-hidden"
      style={{
        maskImage: "linear-gradient(to right, transparent, black 10%, black 90%, transparent)",
        WebkitMaskImage: "linear-gradient(to right, transparent, black 10%, black 90%, transparent)",
      }}
    >
      <style>{`@keyframes infinite-cards-scroll { to { transform: translateX(-50%); } }`}</style>
      <div
        className="flex w-max animate-[infinite-cards-scroll_28s_linear_infinite] gap-4 group-hover:[animation-play-state:paused] motion-reduce:animate-none"
        style={{ animationDirection: direction === "right" ? "reverse" : "normal" }}
      >
        {loop.map((item, i) => (
          <div
            key={i}
            className="w-64 shrink-0 rounded-xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-neutral-950"
          >
            <p className="text-sm text-slate-600 dark:text-slate-300">&ldquo;{item.quote}&rdquo;</p>
            <p className="mt-2 text-xs font-medium text-slate-400 dark:text-slate-500">{item.name}</p>
          </div>
        ))}
      </div>
    </div>
  );
}
